import { mkdirSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
/** Best-effort write: creates parent dirs and never throws (a failed artifact
 * write must not stall the run). Callers needing atomicity use their own path. */
export function writeFileBestEffort(target, content) {
    try {
        mkdirSync(dirname(target), { recursive: true });
        writeFileSync(target, content);
    }
    catch {
        // Intentionally swallowed: replay artifacts must never block the run.
    }
}
/** Make a value safe as a single path segment; "item" when it reduces to empty. */
export function sanitizeFilename(value) {
    const cleaned = value.replace(/[^A-Za-z0-9._-]/g, "_");
    return cleaned.length > 0 ? cleaned : "item";
}
